def __getattr__(name: str) -> Any:
    module = _MODULES.get(name)
    if module is None:
        raise AttributeError(f"module {__name__!r} has no attribute {name!r}")
    value = getattr(importlib.import_module(f"didit.types.{module}"), name)
    globals()[name] = value
    return value


def __dir__() -> list[str]:
    return __all__
